// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;
    function setUp() public { c = new Reentrancy_bonus(); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(c));
        vm.deal(address(c), 1000 ether);
        vm.prank(recipient);
        try c.getFirstWithdrawalBonus(recipient) {} catch {}
        uint256 balBefore = recipient.balance;
        vm.prank(recipient);
        try c.withdrawReward(recipient) {} catch {}
        uint256 balAfter = recipient.balance;
        assertTrue(balAfter == balBefore);
    }
}
